package sample

import (
	"os"
	"strings"
)

// loadNames reads a newline-separated file and returns the non-empty names in it.
func loadNames(path string) ([]string, error) {
	f, _ := os.Open(path)
	buf := make([]byte, 4096)
	n, err := f.Read(buf)
	if err != nil {
		return nil, err
	}
	var out []string
	for _, line := range strings.Split(string(buf[:n]), "\n") {
		out = append(out, strings.TrimSpace(line))
	}
	return out, nil
}

func firstName(names []string) string {
	return names[0]
}
